package io.github.jesterportfolio.hearth.survival.enchants;
import java.util.*;import java.util.random.RandomGenerator;
import org.bukkit.inventory.*;
/** GUI는 물품을 보관하지 않고 원본 슬롯을 지목한다. 난수와 결과는 요청 하나에 고정한다. */
public final class EnchantOperations {
    public enum Action { APPLY,FUSE,EXTRACT,IDENTIFY,GRANT }
    public enum Failure { ALL,ONE,KEEP }
    public record Request(UUID id,Action action,int first,int second,String enchant,int protection,int boost,long generation){public Request{if(first<0||first>=41||second< -1||second>=41||protection< -1||protection>=41||boost< -1||boost>=41)throw new IllegalArgumentException("ENCHANT_SLOT");}}
    public record Rules(boolean enabled,Formula cost,Formula success,Formula destroy,Failure failure,boolean recoverable,Map<String,Integer> materials){public Rules{materials=Map.copyOf(materials);}}
    public record Plan(ItemStack[] after,String outcome,double chance,double roll,long cost,String fingerprint){public Plan{after=after.clone();}}
    private final EnchantItems items;
    public EnchantOperations(EnchantItems items){this.items=items;}
    public Plan plan(Request request,ItemStack[] original,EnchantCatalog.Snapshot catalog,Rules rules,Map<String,Integer> limits,RandomGenerator random){if(!rules.enabled()||request.generation()!=catalog.generation())throw new IllegalArgumentException("ENCHANT_OPERATION_DISABLED_OR_STALE");var after=Arrays.stream(original).map(i->i==null?null:i.clone()).toArray(ItemStack[]::new);var source=Objects.requireNonNull(after[request.first()]);var definition=Objects.requireNonNull(catalog.definitions().get(request.enchant()));if(!definition.enabled()&&request.action()!=Action.EXTRACT)throw new IllegalArgumentException("ENCHANT_DISABLED");var book=items.book(source);int level=request.action()==Action.EXTRACT?items.read(source).getOrDefault(request.enchant(),0):book.map(EnchantItems.Book::level).orElse(1);if(level<1||level>1000||request.action()!=Action.EXTRACT&&level>definition.maxLevel())throw new IllegalArgumentException("ENCHANT_LEVEL");var vars=Map.of("level",(double)level);double probability=Math.clamp(rules.success().evaluate(vars),0,1),destroy=Math.clamp(rules.destroy().evaluate(vars),0,1);long cost=(long)Math.floor(rules.cost().evaluate(vars));if(cost<0||cost>1_000_000_000_000L)throw new IllegalArgumentException("ENCHANT_COST");
        if(request.action()==Action.APPLY){var b=book.orElseThrow();if(b.kind()!=EnchantItems.Kind.BOOK||!b.id().equals(request.enchant())||request.second()<0||request.second()==request.first())throw new IllegalArgumentException("ENCHANT_BOOK_TARGET");var gear=Objects.requireNonNull(after[request.second()]);if(gear.getAmount()!=1||definition.equipment().stream().noneMatch(t->EnchantItems.matches(t,gear.getType())))throw new IllegalArgumentException("ENCHANT_EQUIPMENT");var old=items.read(gear);if(old.getOrDefault(b.id(),0)>=level)throw new IllegalArgumentException("ENCHANT_LEVEL_NOT_INCREASED");for(var id:old.keySet())if(definition.conflicts().contains(id)||Optional.ofNullable(catalog.definitions().get(id)).map(d->d.conflicts().contains(b.id())).orElse(false))throw new IllegalArgumentException("ENCHANT_CONFLICT");String slot=slot(gear);if(!definition.slots().contains(slot))throw new IllegalArgumentException("ENCHANT_EQUIPMENT_SLOT");int cap=limits.getOrDefault(slot,0);for(var entry:limits.entrySet())if(entry.getKey().startsWith("type:")&&EnchantItems.matches(entry.getKey().substring(5),gear.getType()))cap=Math.min(cap,entry.getValue());if(!old.containsKey(b.id())&&old.size()>=cap)throw new IllegalArgumentException("ENCHANT_SLOT_LIMIT");probability=Math.clamp(probability*b.success(),0,1);destroy=Math.clamp(destroy*b.destroy(),0,1);}
        else if(request.action()==Action.FUSE){var b=book.orElseThrow();if(b.kind()!=EnchantItems.Kind.BOOK||!b.id().equals(request.enchant())||level>=definition.maxLevel()||request.second()<0)throw new IllegalArgumentException("ENCHANT_FUSION");var other=items.book(after[request.second()]).orElseThrow();if(!b.id().equals(other.id())||level!=other.level()||other.kind()!=EnchantItems.Kind.BOOK||request.first()==request.second()&&source.getAmount()<2)throw new IllegalArgumentException("ENCHANT_FUSION_PAIR");}
        else if(request.action()==Action.EXTRACT){if(!rules.recoverable()||source.getAmount()!=1)throw new IllegalArgumentException("ENCHANT_NOT_RECOVERABLE");}
        else if(request.action()==Action.IDENTIFY){if(book.orElseThrow().kind()!=EnchantItems.Kind.UNIDENTIFIED)throw new IllegalArgumentException("ENCHANT_IDENTIFIED");}
        if(request.protection()>=0||request.boost()>=0){if(request.action()!=Action.APPLY)throw new IllegalArgumentException("ENCHANT_AUXILIARY");var used=new HashSet<>(List.of(request.first(),request.second()));for(int index:new int[]{request.protection(),request.boost()})if(index>=0&&!used.add(index))throw new IllegalArgumentException("ENCHANT_AUXILIARY_SLOT");if(request.protection()>=0&&items.book(after[request.protection()]).orElseThrow().kind()!=EnchantItems.Kind.PROTECTION)throw new IllegalArgumentException("ENCHANT_PROTECTION");if(request.boost()>=0){var boost=items.book(after[request.boost()]).orElseThrow();if(boost.kind()!=EnchantItems.Kind.BOOST)throw new IllegalArgumentException("ENCHANT_BOOST");probability=Math.clamp(probability+boost.boost(),0,1);}}
        // Configured costs are paid in the same immutable after-payload and PG wallet transaction.
        var protectedSlots=new HashSet<Integer>();for(int i:new int[]{request.first(),request.second(),request.protection(),request.boost()})if(i>=0)protectedSlots.add(i);
        for(var entry:rules.materials().entrySet()){int left=entry.getValue();if(left<1||left>4096)throw new IllegalArgumentException("ENCHANT_MATERIAL_AMOUNT");for(int i=0;i<36&&left>0;i++){var item=after[i];if(protectedSlots.contains(i)||item==null||item.hasItemMeta()||!item.getType().name().equals(entry.getKey()))continue;int used=Math.min(left,item.getAmount());left-=used;take(after,i,used);}if(left>0)throw new IllegalArgumentException("ENCHANT_MATERIALS");}
        if(request.action()==Action.IDENTIFY)probability=1;double roll=request.action()==Action.IDENTIFY?0:random.nextDouble();boolean success=roll<probability;double destructionRoll=request.action()==Action.APPLY&&!success&&request.protection()<0?random.nextDouble():-1;String outcome=success?"SUCCESS":"FAIL";
        switch(request.action()){
            case APPLY->{take(after,request.first(),1);if(request.boost()>=0)take(after,request.boost(),1);if(request.protection()>=0)take(after,request.protection(),1);var gear=after[request.second()];if(success){var map=new HashMap<>(items.read(gear));map.put(request.enchant(),level);after[request.second()]=items.write(gear,map);}else if(request.protection()<0&&destructionRoll<destroy){after[request.second()]=null;outcome="DESTROYED";}}
            case FUSE->{if(success||rules.failure()==Failure.ALL){take(after,request.first(),1);take(after,request.second(),1);}else if(rules.failure()==Failure.ONE)take(after,request.first(),1);if(success)insert(after,items.book(new EnchantItems.Book(request.enchant(),level+1,book.orElseThrow().success(),book.orElseThrow().destroy(),EnchantItems.Kind.BOOK,0)));}
            case EXTRACT->{var map=new HashMap<>(items.read(source));map.remove(request.enchant());after[request.first()]=items.write(source,map);if(success)insert(after,items.book(new EnchantItems.Book(request.enchant(),level,1,0,EnchantItems.Kind.BOOK,0)));}
            case IDENTIFY->{take(after,request.first(),1);var b=book.orElseThrow();insert(after,items.book(new EnchantItems.Book(b.id(),b.level(),b.success(),b.destroy(),EnchantItems.Kind.BOOK,0)));success=true;outcome="IDENTIFIED";}
            case GRANT->throw new IllegalArgumentException("ENCHANT_GRANT_USE_ISSUER");
        }
        String fingerprint=request.action()+"/"+request.enchant()+"/"+level+"/"+request.first()+"/"+request.second()+"/"+catalog.generation()+"/"+cost+"/"+probability+"/"+roll+"/breakChance="+destroy+"/breakRoll="+destructionRoll;return new Plan(after,outcome,probability,roll,cost,fingerprint);
    }
    public static String slot(ItemStack item){String name=item.getType().name();return name.endsWith("_HELMET")?"HEAD":name.endsWith("_CHESTPLATE")?"CHEST":name.endsWith("_LEGGINGS")?"LEGS":name.endsWith("_BOOTS")?"FEET":item.getType()==org.bukkit.Material.SHIELD?"OFF_HAND":"MAIN_HAND";}
    private static void take(ItemStack[] items,int index,int amount){var item=Objects.requireNonNull(items[index]);if(item.getAmount()<amount)throw new IllegalArgumentException("ENCHANT_INPUT_QUANTITY");item.subtract(amount);if(item.isEmpty())items[index]=null;}
    public static void insert(ItemStack[] inventory,ItemStack value){for(int i=0;i<36;i++)if(inventory[i]==null||inventory[i].isEmpty()){inventory[i]=value.clone();return;}throw new IllegalArgumentException("ENCHANT_INVENTORY_FULL");}
}
